-- ====================================================================
-- 05_seed_geo_coordinates.sql
-- Latitude / longitude for every location the source data ships to.
--
-- Source  : Fact&dim-csv/Dim_Geography.csv — a geocoding pass the
--           bootcamp team ran over the distinct shipping locations.
--           This is the ONLY data in the olap schema that does not
--           come from the oltp schema, hence the seed_ prefix: it is
--           an input to the model, not a derivation of one.
-- Grain   : one row per (city, state, country, region), matching the
--           3,772 distinct shipping locations in oltp.shipping
--           exactly — 100% coverage, no nulls, no duplicates.
-- Used by : 11_dim_geography.sql, which left-joins it on all four
--           columns. 90_checks.sql asserts the join loses nothing.
--
-- Region is part of the key, not decoration: the source files seven
-- Austrian and Mongolian cities under two regions each, so
-- (city, state, country) alone is not unique. See 11_dim_geography.
--
-- Coordinates are rounded to 7 decimal places (~1 cm), which is far
-- past the precision of a city centroid and keeps the values exact
-- under numeric rather than carrying float noise.
-- ====================================================================
DROP TABLE IF EXISTS olap.seed_geo_coordinates CASCADE;

CREATE TABLE olap.seed_geo_coordinates (
    city        varchar(64)    NOT NULL,
    state       varchar(64)    NOT NULL,
    country     varchar(32)    NOT NULL,
    region      varchar(16)    NOT NULL,
    latitude    numeric(10, 7) NOT NULL,
    longitude   numeric(11, 7) NOT NULL,
    PRIMARY KEY (city, state, country, region)
);

COMMENT ON TABLE olap.seed_geo_coordinates IS
    'External enrichment: city-centroid coordinates for the distinct '
    'shipping locations. Input to dim_geography, not derived from oltp.';

